def slots_to_list(apps, schema_editor):
    """Each runner's fixed slots become entries at the end of its list, in the
    order the box tried them: token 1, token 2, then the API key. The values are
    already ciphertext under the same key, so nothing is decrypted."""
    RunnerCredential = apps.get_model("harness", "RunnerCredential")
    RunnerLogin = apps.get_model("harness", "RunnerLogin")
    for cred in RunnerCredential.objects.all():
        last = RunnerLogin.objects.filter(runner_id=cred.runner_id).order_by("-position").first()
        position = (last.position + 1) if last else 0
        for kind, value, name in (("token", cred.claude_token_enc, cred.claude_token_label),
                                  ("token", cred.claude_token_secondary_enc,
                                   cred.claude_token_secondary_label),
                                  ("api_key", cred.claude_api_key_enc, "")):
            if not value:
                continue
            RunnerLogin.objects.create(runner_id=cred.runner_id, key=secrets.token_hex(4),
                                       kind=kind, value_enc=value, name=name, position=position)
            position += 1


